    function configureRound(){const p=(round-1)/Math.max(1,targetRounds-1);width=.82-Math.pow(p,1.12)*.61;baseTarget=rand(0,Math.PI*2);targetAngle=baseTarget;roundStart=performance.now();stage.classList.toggle('ritual-final-round',round===targetRounds);stage.classList.toggle('ritual-dual-round',round>=Math.ceil(targetRounds/2));instruction.textContent=round>=Math.ceil(targetRounds/2)?'DUAL LOCK · BOTH OPPOSITE MARKS MUST ALIGN TOGETHER':'LINE UP THE POINTER WITH THE GREEN MARK';updateTargetArt();}
    function update(){const r=Math.min(targetRounds,Math.max(0,round));$('[data-ritual-round]',root).textContent=String(r||1).padStart(2,'0');$('.ritual-core small',root).textContent=`ROUND / ${targetRounds}`;$('[data-ritual-round-readout]',root).textContent=`${r} / ${targetRounds}`;$('[data-ritual-score]',root).textContent=score;$('[data-ritual-chain]',root).textContent=chain;$('[data-ritual-best]',root).textContent=best;$('[data-ritual-precision]',root).textContent=precision.length?`${Math.round(precision.reduce((a,b)=>a+b,0)/precision.length)}%`:'-';$('[data-ritual-final]',root).textContent=round>=Math.ceil(targetRounds/2)?'DUAL LOCK ACTIVE':round>=Math.ceil(targetRounds*.36)?'TARGETS ACCELERATING':'SINGLE LOCK';$('[data-ritual-progress]',root).style.width=`${clamp((round/targetRounds)*100,0,100)}%`;}
